  showNestedModal(i18nText('map.new_item.title',{kind:kindLabel}),`<div class="field"><label>{{i18n:dynamic.html.text.label.450ca425}}</label><input id="newMapItemName" value="${escapeHtml(defaultName)}" autofocus></div><div class="field"><label>{{i18n:dynamic.html.text.label.40a966a4}}</label><textarea id="newMapItemDescription" rows="4"></textarea></div><div class="field"><div class="section-label">{{i18n:dynamic.html.text.div.2fc984ee}}</div><div id="newMapItemLinks" class="link-list">${renderPendingMapItemLinks(pendingLinks)}</div><button id="newMapItemAddLink" type="button" class="full-soft" style="margin-top:8px">${LINK_ICON} ${escapeHtml(i18nSource('Add link'))}</button></div>`,`<button id="cancelNewMapItem">{{i18n:dynamic.html.text.button.92113f72}}</button><button id="createNewMapItem">${escapeHtml(i18nText('map.new_item.create',{kind:kindLabel}))}</button>`);
  const name=$('#newMapItemName'),description=$('#newMapItemDescription'),linksBox=$('#newMapItemLinks');
  const renderLinks=()=>{linksBox.innerHTML=renderPendingMapItemLinks(pendingLinks);$$('[data-pending-map-link-delete]').forEach(button=>button.onclick=()=>{pendingLinks.splice(entityId(button.dataset.pendingMapLinkDelete),1);renderLinks()})};
  $('#newMapItemAddLink').onclick=()=>openPendingMapItemLinker(pendingLinks,renderLinks);$('#cancelNewMapItem').onclick=()=>closeModal();
  let creating=false;const create=async()=>{if(creating)return;const title=name.value.trim()||defaultName;creating=true;$('#createNewMapItem').disabled=true;const start=isSpan?Math.max(0,p-.04):p,end=isSpan?Math.min(1,p+.06):null,payload={item_type:type,title,description:description.value||'',planned_start:start,schematic_start:start,...(isSpan?{planned_end:end,schematic_end:end}:{})};let created;try{await withStructuralUndo(`Create Map ${kind}: ${title}`,async()=>{created=await api(`/api/map-lines/${line.id}/items`,{method:'POST',body:JSON.stringify(payload)});for(const link of pendingLinks)await api('/api/references',{method:'POST',body:JSON.stringify({source_type:'map_item',source_id:String(created.id),target_type:link.type,target_id:String(link.id)})})},{view:'maps',mapId:state.currentMap.id});closeModal(false);state.currentMapLineId=line.id;state.selectedMapItemId=created.id;await reloadCurrentMap();openMapItemInspector(created.id);return created}catch(error){creating=false;$('#createNewMapItem').disabled=false;toast(error.message||`${kind} could not be created.`,4800)}};
  $('#createNewMapItem').onclick=create;name.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();create()}};queueMicrotask(()=>{name.focus();name.select()});
