async function branchNewLineHere(sourceLine,position,itemId=null){if(position===null||position===undefined)return;const name=await textDialog('Branch New Line',{label:'Line name',value:i18nSource('New Branch'),confirmLabel:'Create Branch'});if(!name?.trim())return;let newLine,newItem;await withStructuralUndo(`Branch new Map line: ${name.trim()}`,async()=>{newLine=await api(`/api/maps/${state.currentMap.id}/lines`,{method:'POST',body:JSON.stringify({name:name.trim(),planned_start:position,planned_end:Math.min(1,position+.12),schematic_start:position,schematic_end:Math.min(1,position+.12)})});newItem=await api(`/api/map-lines/${newLine.id}/items`,{method:'POST',body:JSON.stringify({item_type:'stop',title:i18nSource('Branch'),planned_start:position,schematic_start:position})});const from=itemId?{from_item_id:itemId}:{from_line_id:sourceLine.id,from_edge:'point',from_planned_position:position,from_schematic_position:position};await api(`/api/maps/${state.currentMap.id}/junctions`,{method:'POST',body:JSON.stringify({kind:'branch',...from,to_item_id:newItem.id})})},{view:'maps',mapId:state.currentMap.id,undoScope:'maps'});state.currentMapLineId=newLine.id;await reloadCurrentMap()}

async function configureCurrentMap(){
  if(!state.currentMap||!state.mapData?.map)return;
  closeMapInspector();
  const map=state.mapData.map,stored=String(map.background||MAP_DEFAULT_BG).toLowerCase(),usesDefault=stored===MAP_DEFAULT_BG;
  showModal('Map Details',`<div class="field"><label>{{i18n:dynamic.html.text.label.450ca425}}</label><input id="mapDetailsName" value="${escapeHtml(map.name)}"></div><div class="field"><label>{{i18n:dynamic.html.text.label.40a966a4}}</label><textarea id="mapDetailsDescription" rows="4">${escapeHtml(map.description||'')}</textarea></div><div class="field"><label>{{i18n:dynamic.html.text.label.12f918f5}}</label><select id="mapDetailsBackgroundMode"><option value="default" ${usesDefault?'selected':''}>{{i18n:dynamic.html.text.option.15e6e90c}}</option><option value="custom" ${usesDefault?'':'selected'}>{{i18n:dynamic.html.text.option.d207fdbe}}</option></select></div><div id="mapDetailsCustomBackground" class="field ${usesDefault?'hidden':''}"><label>{{i18n:dynamic.html.text.label.15274020}}</label><div class="color-input-row"><input id="mapDetailsBackground" type="color" value="${escapeHtml(usesDefault?MAP_DEFAULT_BG:stored)}"><input id="mapDetailsBackgroundText" value="${escapeHtml(usesDefault?MAP_DEFAULT_BG:stored)}" maxlength="7"></div></div><p class="small-muted map-details-background-note">{{i18n:dynamic.html.text.p.b7a06247}}</p>`,'');
  const name=$('#mapDetailsName'),description=$('#mapDetailsDescription'),mode=$('#mapDetailsBackgroundMode'),custom=$('#mapDetailsCustomBackground'),picker=$('#mapDetailsBackground'),text=$('#mapDetailsBackgroundText');
  const commit=async(patch,label)=>{await withStructuralUndo(label,()=>api(`/api/maps/${map.id}`,{method:'PATCH',body:JSON.stringify(patch)}),{view:'maps',mapId:map.id});Object.assign(map,patch);const summary=state.maps.find(row=>entityId(row.id)===entityId(map.id));if(summary)Object.assign(summary,patch);renderMapTree();renderMapControls();if(Object.hasOwn(patch,'background'))renderMapVisual()};
  name.onchange=async()=>{const value=name.value.trim();if(!value){name.value=map.name;return toast('A Map needs a name.')}if(value===map.name)return;const previous=map.name;try{await commit({name:value},`Rename Map: ${previous}`)}catch(error){name.value=map.name;toast(error?.message||'Map name could not be saved.',4600)}};
  description.onchange=async()=>{const value=description.value;if(value===map.description)return;try{await commit({description:value},`Update Map description: ${map.name}`)}catch(error){description.value=map.description||'';toast(error?.message||'Map description could not be saved.',4600)}};
  const syncMode=()=>custom.classList.toggle('hidden',mode.value!=='custom');
  mode.onchange=async()=>{syncMode();if(mode.value==='default'&&String(map.background||MAP_DEFAULT_BG).toLowerCase()!==MAP_DEFAULT_BG){try{await commit({background:MAP_DEFAULT_BG},`Use default Map background: ${map.name}`)}catch(error){mode.value='custom';syncMode();toast(error?.message||'Map background could not be saved.',4600)}}};
  picker.oninput=()=>text.value=picker.value;
  const commitCustom=async()=>{const value=text.value.trim().toLowerCase();if(!/^#[0-9a-f]{6}$/i.test(value))return toast('Use a six-digit hex color, for example #F3F3F1.');picker.value=value;if(value===String(map.background||'').toLowerCase())return;try{await commit({background:value},`Change Map background: ${map.name}`)}catch(error){text.value=map.background||MAP_DEFAULT_BG;picker.value=map.background||MAP_DEFAULT_BG;toast(error?.message||'Map background could not be saved.',4600)}};
  picker.onchange=commitCustom;text.onchange=commitCustom;text.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(text.value.trim()))picker.value=text.value.trim()};syncMode();
}

async function autoArrangeCurrentMap(){if(!state.currentMap)return;await withStructuralUndo(`Auto arrange Map: ${state.currentMap.name}`,()=>api(`/api/maps/${state.currentMap.id}/auto-arrange`,{method:'POST'}),{view:'maps',mapId:state.currentMap.id});await reloadCurrentMap();toast('Map arranged')}
