async function deleteCurrentMap(){if(!state.currentMap)return;const map=state.currentMap;if(!await confirmDialog('Delete Map',i18nText('confirm.delete_map',{name:map.name}),{confirmLabel:'Delete Map',danger:true}))return;await withStructuralUndo(`Delete Map: ${map.name}`,()=>api(`/api/maps/${map.id}`,{method:'DELETE'}),{view:'maps'});dismissModalTree();state.mapTreeCache.delete(map.id);state.currentMap=null;state.mapData=null;state.currentMapLineId=null;await refresh(false);await renderMapsWorkspace();closeMapInspector()}
async function setMapSetting(field,value,label){if(!state.currentMap||state.mapData.map[field]===value)return;await withStructuralUndo(`${label}: ${state.currentMap.name}`,()=>api(`/api/maps/${state.currentMap.id}`,{method:'PATCH',body:JSON.stringify({[field]:value})}),{view:'maps',mapId:state.currentMap.id});await reloadCurrentMap()}
function positionMapViewPopover(){const button=$('#mapViewBtn'),pop=$('#mapViewPopover');if(!button||!pop||pop.classList.contains('hidden'))return;const rect=button.getBoundingClientRect(),margin=8,width=pop.offsetWidth||254;let left=rect.right-width;left=Math.max(margin,Math.min(innerWidth-width-margin,left));let top=rect.bottom+6;if(top+(pop.offsetHeight||360)>innerHeight-margin)top=Math.max(margin,rect.top-(pop.offsetHeight||360)-6);pop.style.left=`${left}px`;pop.style.top=`${top}px`}
function closeMapViewPopover(){const pop=$('#mapViewPopover'),button=$('#mapViewBtn');if(!pop||pop.classList.contains('hidden'))return;pop.classList.add('hidden');button?.setAttribute('aria-expanded','false')}
function toggleMapViewPopover(){const pop=$('#mapViewPopover'),button=$('#mapViewBtn');if(!pop||!button||button.disabled)return;const opening=pop.classList.contains('hidden');if(!opening)return closeMapViewPopover();closeViewPopover();closeCanvasViewPopover();$('#mapViewTooltip')?.classList.add('hidden');renderMapControls();pop.classList.remove('hidden');button.setAttribute('aria-expanded','true');positionMapViewPopover()}

function setMapZoom(value){state.mapZoom=Math.max(MAP_ZOOM_MIN,Math.min(MAP_ZOOM_MAX,value));renderMapVisual();const reset=$('#mapZoomReset');if(reset)reset.textContent=`${Math.round(state.mapZoom*100)}%`;queueMapViewportPersist()}
function mapFitsViewportAtZoom(zoom,availableW,availableH){const layout=mapLogicalLayout(state.mapData,zoom);return layout.width*zoom<=availableW+.5&&layout.height*zoom<=availableH+.5}
function fitMap(){if(!state.mapData)return;const stage=$('#mapStage'),pad=24,availableW=Math.max(1,stage.clientWidth-pad),availableH=Math.max(1,stage.clientHeight-pad),fitMax=Math.min(1.4,MAP_ZOOM_MAX);let low=MAP_ZOOM_MIN,high=fitMax;if(mapFitsViewportAtZoom(high,availableW,availableH))low=high;else if(mapFitsViewportAtZoom(low,availableW,availableH)){for(let i=0;i<28;i++){const mid=(low+high)/2;if(mapFitsViewportAtZoom(mid,availableW,availableH))low=mid;else high=mid}}setMapZoom(low);requestAnimationFrame(()=>stage.scrollTo({left:0,top:0}))}

